package com.morghtak.kharidmanager;
import java.util.*;
public class PersianDate {
 public static String today(){Calendar c=Calendar.getInstance();int[] j=toJalali(c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH));return String.format(Locale.US,"%04d/%02d/%02d",j[0],j[1],j[2]);}
 public static int[] toJalali(int gy,int gm,int gd){int[] gdm={0,31,28,31,30,31,30,31,31,30,31,30,31};int gy2=gm>2?gy+1:gy;int days=355666+365*gy+((gy2+3)/4)-((gy2+99)/100)+((gy2+399)/400)+gd;for(int i=1;i<gm;i++)days+=gdm[i];int jy=-1595+33*(days/12053);days%=12053;jy+=4*(days/1461);days%=1461;if(days>365){jy+=(days-1)/365;days=(days-1)%365;}int jm=days<186?1+days/31:7+(days-186)/30;int jd=1+(days<186?days%31:(days-186)%30);return new int[]{jy,jm,jd};}
 public static int[] toGregorian(int jy,int jm,int jd){int jy2=jy+1595;int days=-355668+365*jy2+(jy2/33)*8+((jy2%33+3)/4)+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);int gy=400*(days/146097);days%=146097;if(days>36524){gy+=100*((--days)/36524);days%=36524;if(days>=365)days++;}gy+=4*(days/1461);days%=1461;if(days>365){gy+=(days-1)/365;days=(days-1)%365;}int gd=days+1;int[] sal={31,(gy%4==0&&gy%100!=0)||gy%400==0?29:28,31,30,31,30,31,31,30,31,30,31};int gm=0;while(gm<12&&gd>sal[gm])gd-=sal[gm++];return new int[]{gy,gm+1,gd};}
 public static long millis(String s,String time){try{String[] a=AppData.digits(s).split("/");String[] t=AppData.digits(time).split(":");int[] g=toGregorian(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]));Calendar c=Calendar.getInstance();c.set(g[0],g[1]-1,g[2],Integer.parseInt(t[0]),Integer.parseInt(t[1]),0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}catch(Exception e){return -1;}}
}
